// Overworld road texture (Town Nav) — a single tileable strip: light
// concrete sidewalk top and bottom, dark asphalt with a centered dashed
// lane line in between. Repeated left-to-right across the street view,
// scaled down to match the game's existing ROAD_HALF_HEIGHT band (see
// game/street.ts) rather than drawn at native resolution.
export const ROAD_TEXTURE_DATA_URI = "data:image/jpeg;base64,";
// Native pixel dimensions of the source strip above, and the row range
// (top-inclusive, bottom-exclusive) that's the actual asphalt band —
// used to compute the scale factor and vertical placement so the baked-in
// dashed centerline lands exactly on the game's own road centerline.
export const ROAD_TEXTURE_WIDTH = 700;
export const ROAD_TEXTURE_HEIGHT = 470;
export const ROAD_TEXTURE_ROAD_TOP = 78;
export const ROAD_TEXTURE_ROAD_BOTTOM = 389;
